// committedFile is the generated file as `task gen` writes it, relative to this package.
var committedFile = filepath.Join("..", "..", "..", "..", "web", "src", "protocol", "registry.gen.ts")

// TestCommittedFileIsCurrent is the registry half of `task gen:check` inside `go test`: a Registry change without
// `task gen` fails here too. Line endings do not count: a checkout with core.autocrlf (Git for Windows' default) has
// CRLF where the generator writes LF, and git diff, so `task gen:check`, ignores that as well.
func TestCommittedFileIsCurrent(t *testing.T) {
	want, err := Generate(protocol.Registry)
	if err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(committedFile)
	if err != nil {
		t.Fatal(err)
	}
	got = bytes.ReplaceAll(got, []byte("\r\n"), []byte("\n"))
	if !bytes.Equal(got, want) {
		t.Errorf("%s is not what the generator writes for protocol.Registry: run task gen and commit the result",
			committedFile)
	}
}

func TestGenerateIsDeterministic(t *testing.T) {
	first, err := Generate(protocol.Registry)
	if err != nil {
		t.Fatal(err)
	}
	for range 5 {
		again, err := Generate(protocol.Registry)
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(first, again) {
			t.Fatal("two runs gave different output")
		}
	}
}

// TestGenerateRegistry checks the output for the real Registry against 01 §7: one line per message, per direction.
func TestGenerateRegistry(t *testing.T) {
	src, err := Generate(protocol.Registry)
	if err != nil {
		t.Fatal(err)
	}
	out := string(src)
	for _, want := range []string{
		"// Code generated by tsregistry from protocol.Registry (internal/protocol/registry.go). DO NOT EDIT.\n",
		"import type * as P from './types.gen';\n",
		// requests: payload, result, reply
		"  hello: { data: P.Hello; result: P.Welcome; reply: 'welcome' };\n",
		"  'room.join': { data: P.RoomJoin; result: P.RoomJoinResult; reply: 'ok' };\n",
		"  'room.leave': { data: Record<string, never>; result: Record<string, never>; reply: 'ok' };\n",
		"  /** Roles: full, publisher, agent. */\n  'share.stop': { data: P.ShareStop; result: Record<string, never>; reply: 'ok' };\n",
		"  /** Roles: full, publisher, agent. */\n  'share.start': { data: P.ShareStart; result: P.ShareParams; reply: 'ok' };\n",
		"  /** Feature agent.relay. */\n  'agent.send': { data: P.AgentSend; result: P.AgentSendResult; reply: 'ok' };\n",
		// notifications and server messages; stats has a payload per direction
		"export interface ClientNotifications {\n  ping: P.Ping;\n",
		"  stats: P.ClientStats;\n",
		"  stats: P.ServerStats;\n",
		"  'pc.close': P.PCClose;\n",
		"  ok: P.RoomJoinResult | Record<string, never> | P.ShareParams | P.SubscribeResult | P.AgentSendResult;\n",
		"  error: P.Error;\n",
		"  /** Milestone M2. Feature user.connections. */\n  'user.connections': P.UserConnections;\n",
		// runtime values
		"export const clientRequestTypes = [\n  'hello',\n",
		"] as const satisfies readonly P.MessageType[];\n",
		"  hello: 'welcome',\n  'room.join': 'ok',\n",
		"  'agent.recv': 'agent.relay',\n",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("output lacks %q", want)
		}
	}
	// protocol.Empty is only {}: tygo's `interface Empty {}` would accept any value.
	if strings.Contains(out, "P.Empty") {
		t.Error("output uses P.Empty, not Record<string, never>")
	}
	// pc.close is client->server only; pc.offer goes both ways.
	if n := strings.Count(out, "  'pc.close': P.PCClose;\n"); n != 1 {
		t.Errorf("pc.close appears in %d maps, want 1", n)
	}
	if n := strings.Count(out, "  'pc.offer': P.PCOffer;\n"); n != 2 {
		t.Errorf("pc.offer appears in %d maps, want 2", n)
	}
	for _, s := range protocol.Registry {
		if !strings.Contains(out, "  '"+string(s.Type)+"',\n") && !strings.Contains(out, "  "+string(s.Type)+": ") {
			t.Errorf("%s is missing", s.Type)
		}
	}
}

func TestGenerateRejects(t *testing.T) {
	ok := protocol.Spec{Type: "ok", Dir: protocol.DirServerToClient, Kind: protocol.KindReply}
	join := protocol.Spec{Type: "room.join", Dir: protocol.DirClientToServer, Kind: protocol.KindRequest,
		Payload: protocol.RoomJoin{}, Reply: "ok", Result: protocol.RoomJoinResult{}}
	ping := protocol.Spec{Type: "ping", Dir: protocol.DirClientToServer, Kind: protocol.KindNotification,
		Payload: protocol.Ping{}}
	with := func(s protocol.Spec, change func(*protocol.Spec)) protocol.Spec {
		change(&s)
		return s
	}

	if _, err := Generate([]protocol.Spec{join, ok, ping}); err != nil {
		t.Fatalf("the valid base registry fails: %v", err)
	}
	for _, c := range []struct {
		name  string
		specs []protocol.Spec
		want  string
	}{
		{"anonymous struct payload", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Payload = struct{ T int }{} })}, "not a named struct type of package protocol"},
		{"payload of another package", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Payload = time.Time{} })}, "time.Time"},
		{"pointer payload", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Payload = &protocol.Ping{} })}, "*protocol.Ping"},
		{"non-struct payload", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Payload = protocol.RoleFull })}, "protocol.Role"},
		{"notification without payload", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Payload = nil })}, "no payload type"},
		{"request without result", []protocol.Spec{ok, with(join, func(s *protocol.Spec) { s.Result = nil })}, "no payload type"},
		{"request without reply", []protocol.Spec{ok, with(join, func(s *protocol.Spec) { s.Reply = "" })}, "needs a Reply"},
		{"reply the server never sends", []protocol.Spec{join}, `its reply "ok" is not a server->client message`},
		{"reply without payload that answers nothing", []protocol.Spec{ok, ping}, "answers no request"},
		{"duplicate", []protocol.Spec{join, ok, ping, ping}, "a second entry for direction 1"},
		{"both directions in one entry", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Dir = 3 })}, "not exactly one direction"},
		{"server request", []protocol.Spec{join, ok, with(join, func(s *protocol.Spec) { s.Dir = protocol.DirServerToClient })}, "kind 1 is not supported for direction 2"},
		{"client reply", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Kind = protocol.KindReply })}, "kind 2 is not supported for direction 1"},
		{"unknown kind", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Kind = 0 })}, "kind 0 is not supported"},
		{"type with a quote", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Type = "it's" })}, "dotted lowercase"},
		{"type in upper case", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Type = "Room.Join" })}, "dotted lowercase"},
		{"empty type", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Type = "" })}, "dotted lowercase"},
		{"feature with a quote", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Feature = "a'b" })}, "feature"},
		{"feature per direction", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Feature = "x.y" }),
			with(ping, func(s *protocol.Spec) { s.Dir = protocol.DirServerToClient })}, `feature "" differs`},
		{"comment breaker", []protocol.Spec{ok, with(ping, func(s *protocol.Spec) { s.Milestone = "M2 */ x" })}, "comment"},
	} {
		t.Run(c.name, func(t *testing.T) {
			out, err := Generate(c.specs)
			if err == nil {
				t.Fatalf("no error; output:\n%s", out)
			}
			if !strings.Contains(err.Error(), c.want) {
				t.Errorf("error %q does not contain %q", err, c.want)
			}
		})
	}
}

// TestGenerateReportsEveryError: one run lists all problems, not just the first.
func TestGenerateReportsEveryError(t *testing.T) {
	_, err := Generate([]protocol.Spec{
		{Type: "a", Dir: protocol.DirClientToServer, Kind: protocol.KindNotification},
		{Type: "b", Dir: protocol.DirClientToServer, Kind: protocol.KindNotification, Payload: 1},
	})
	if err == nil || !strings.Contains(err.Error(), `Registry[0] "a"`) || !strings.Contains(err.Error(), `Registry[1] "b"`) {
		t.Errorf("err = %v, want both entries named", err)
	}
}

func TestGenerateSmallRegistry(t *testing.T) {
	src, err := Generate([]protocol.Spec{
		{Type: "x.do", Dir: protocol.DirClientToServer, Kind: protocol.KindRequest, Payload: protocol.Empty{},
			Reply: "done", Result: protocol.Pong{}, Roles: []protocol.Role{protocol.RoleViewer}, Since: 2},
		{Type: "done", Dir: protocol.DirServerToClient, Kind: protocol.KindReply},
		{Type: "news", Dir: protocol.DirServerToClient, Kind: protocol.KindNotification, Payload: protocol.Invalidate{}},
	})
	if err != nil {
		t.Fatal(err)
	}
	out := string(src)
	for _, want := range []string{
		"  /** Since protocol version 2. Roles: viewer. */\n  'x.do': { data: Record<string, never>; result: P.Pong; reply: 'done' };\n",
		"export interface ClientNotifications {\n}\n",
		"  done: P.Pong;\n  news: P.Invalidate;\n",
		"export const clientNotificationTypes = [] as const satisfies readonly P.MessageType[];\n",
		"export const messageTypes = [\n  'x.do',\n  'done',\n  'news',\n]",
		"  'x.do': 'done',\n",
		"export const messageFeatures: Readonly<Partial<Record<P.MessageType, P.Feature>>> = {\n};\n",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("output lacks %q\n%s", want, out)
		}
	}
}
